<?php

namespace App\Services\Resume;

use App\Models\CmsPage;
use App\Services\Builder\BuilderRevisions;
use Illuminate\Support\Str;

/**
 * Resume themes = design tokens + a page-builder layout preset (resources/resume/themes.json, generated by
 * scripts/resume/gen_themes.py). Switching theme only changes resume_settings.theme_key; applyLayout() rewrites the
 * resume pages (fa → slug "home", en → slug "en", same translation_group for hreflang) and keeps the previous
 * builder document as a BuilderRevision («resume-theme») so it can be restored from the builder history.
 */
class ResumeThemes
{
    public const PAGE_SLUGS = ['fa' => 'home', 'en' => 'en'];

    private static ?array $catalog = null;

    public static function catalog(): array
    {
        return self::$catalog ??= json_decode((string) file_get_contents(resource_path('resume/themes.json')), true);
    }

    /** Builder document for a theme preset in one language. */
    public static function document(string $key, string $lang): array
    {
        $theme = self::catalog()[$key] ?? abort(404);
        $sections = [];
        foreach ($theme['layout'] as $i => $w) {
            $sections[] = [
                'id' => 's_rz'.$i.'_'.Str::lower(Str::random(6)),
                'label' => $w['type'],
                'fullWidth' => true,
                'columns' => [[
                    'id' => 'c_rz'.$i.'_'.Str::lower(Str::random(6)),
                    'span' => 12,
                    'widgets' => [[
                        'id' => 'w_rz'.$i.'_'.Str::lower(Str::random(6)),
                        'type' => $w['type'],
                        'props' => $w['props'] + ['lang' => $lang, 'full_width' => true, 'show_placeholder' => false],
                    ]],
                ]],
            ];
        }
        if (empty($theme['full_page'])) {
        array_unshift($sections, [
            'id' => 's_rzlang_'.Str::lower(Str::random(6)), 'label' => 'resume.lang_switch', 'fullWidth' => true,
            'columns' => [['id' => 'c_rzlang_'.Str::lower(Str::random(6)), 'span' => 12, 'widgets' => [[
                'id' => 'w_rzlang_'.Str::lower(Str::random(6)), 'type' => 'resume.lang_switch', 'props' => ['variant' => 'pill', 'lang' => $lang],
            ]]]],
        ]);
        }

        return ['version' => 2, 'sections' => $sections, 'page_settings' => ['resume_theme' => $key]];
    }

    /** @param  list<string>  $langs */
    public static function applyLayout(int $tenantId, string $key, array $langs): array
    {
        $group = CmsPage::query()->where('tenant_id', $tenantId)->whereIn('slug', array_values(self::PAGE_SLUGS))->value('translation_group')
            ?: 'resume-'.Str::lower(Str::random(10));
        $out = [];
        foreach ($langs as $lang) {
            $slug = self::PAGE_SLUGS[$lang];
            $page = CmsPage::query()->where('tenant_id', $tenantId)->where('slug', $slug)->first();
            $doc = self::document($key, $lang);
            if ($page) {
                foreach (['builder_draft', 'builder_published'] as $col) {
                    if (is_array($page->{$col}) && $page->{$col}) {
                        BuilderRevisions::record('page', $page, $page->{$col}, 'resume-theme');
                    }
                }
            } else {
                $page = new CmsPage(['tenant_id' => $tenantId, 'slug' => $slug]);
                $page->tenant_id = $tenantId;
                $page->title = $lang === 'en' ? 'Resume' : 'رزومه';
                $page->published = true;
                $page->status = 'published';
            }
            $page->lang = $lang;
            $page->translation_group = $group;
            $page->builder_draft = $doc;
            $page->builder_published = $doc;
            $page->save();
            $out[] = ['lang' => $lang, 'page_id' => $page->id, 'slug' => $slug];
        }
        ResumeScope::set($tenantId);
        $settings = \App\Models\Resume\ResumeSetting::query()->firstOrCreate(['tenant_id' => $tenantId]);
        $settings->update(['theme_key' => $key]);

        return ['theme_key' => $key, 'pages' => $out];
    }
}
